 "content": "from collections import Counter, deque


def transform(grid):
    """Keep and regularize the large solid-color rectangles; discard speckles."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and not seen[yy][xx] and grid[yy][xx] != bg:
                        seen[yy][xx] = True
                        q.append((yy, xx))
            r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
            c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
            area = (r1-r0+1) * (c1-c0+1)
            if area < 4:
                continue
            # A rectangle may contain a few differently colored marker cells.
            # Require its bounding box to be substantially occupied by foreground.
            occupied = sum(grid[y][x] != bg for y in range(r0, r1+1) for x in range(c0, c1+1))
            if occupied / area < 0.65:
                continue
            color = Counter(grid[y][x] for y, x in cells).most_common(1)[0][0]
            for y in range(r0, r1+1):
                for x in range(c0, c1+1):
                    out[y][x] = color
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
